head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDINS31200.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);

    // 기본값 세팅
    scwin.fn_SetDefaultVal();

    //시스템권한 가리기
    if (js_id.indexOf("sysm") == -1) {
        $c.stf.showObj(label_2, false);
        $c.stf.showObj(cmb_pACNT_DIV, false);
        $c.stf.showObj(label_4, false);
        $c.stf.showObj(txb_pASUM_ACNT, false);
        $c.stf.showObj(btn_search_realtime, false);
    }
    var array_grid = [grd_List];
    setResizeGrid(array_grid);
    scwin.ins_search();
};


/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var sToday = $c.ut.cGetToday2();
    edt_TRD_DD_START.setValue(sToday);
    edt_TRD_DD_END.setValue(sToday);
    $c.stf.showObj(panel_5, false);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_List.removeAll();
    txb_TotalCnt.setValue("총 0건");
};


/**
 * 조회
 */
scwin.ins_search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_search")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=INS_LIST_DEPO_CONFRM_RCV_DTL_LIST_INQUIRY" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.search.select.TBLD_B_DEPO_CONFRM_RCV_DTL.dtl" + "&{P}TRD_DD=" + edt_TRD_DD_START.getValue() + "&{P}TRD_DD_END=" + edt_TRD_DD_END.getValue() + "&{P}DEPOPRN_NM=" + txb_pDEPOPRN_NM.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == "ins_search") {
        if ($c.stf.getObjectValue(edt_TRD_DD_START) == "") {
            $c.win.alert("거래일자 시작일을 입력하세요.");
            edt_TRD_DD_START.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TRD_DD_END) == "") {
            $c.win.alert("거래일자 종료일을 입력하세요.");
            edt_TRD_DD_END.focus();
            return false;
        }
    } else if (pGubun == "ins_search_realtime") {
        if ($c.stf.getObjectValue(edt_TRD_DD_START) == "") {
            $c.win.alert("거래일자 시작일을 입력하세요.");
            edt_TRD_DD_START.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TRD_DD_END) == "") {
            $c.win.alert("거래일자 종료일을 입력하세요.");
            edt_TRD_DD_END.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_pDEPOPRN_NM) != "") {
            $c.win.alert("미리보기 조회시 [거래자성명]은 사용 할 수 없습니다.");
            txb_pDEPOPRN_NM.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_pACNT_DIV) == "2") {
            if ($c.stf.getObjectValue(txb_pASUM_ACNT) != "") {
                $c.win.alert("선납계좌 선택시 [가상계좌]는 사용 할 수 없습니다.");
                txb_pASUM_ACNT.focus();
                return false;
            }
        }
    }
    return true;
};


/**
 * 실시간 sap 조회
 */
scwin.ins_search_realtime = function() {
    $c.win.alert('[미리보기] 기능은 실시간 계좌조회 용도이며 시스템관리자 권한에서만 활성화됩니다.');

    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_search_realtime")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);
    var url = "/PrepayInfoAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=sapRealTimeSearch" + "&outputMessageId=INS_LIST_DEPO_CONFRM_RCV_DTL_LIST_INQUIRY" + "&service=krx.lds.ins.etc.services.PrepayInfoApp" +
        //"&queryId=lds.ins.search.select.TBLD_B_DEPO_CONFRM_RCV_DTL.dtl" +
        "&TRD_DD=" + edt_TRD_DD_START.getValue() + "&TRD_DD_END=" + edt_TRD_DD_END.getValue() + "&DEPOPRN_NM=" + txb_pDEPOPRN_NM.getValue() + "&ASUM_ACNT=" + txb_pASUM_ACNT.getValue() + "&ACNT_DIV=" + $c.stf.getObjectValue(cmb_pACNT_DIV);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 * 발생기관 팝업에서 값 받음.
 */
scwin.fn_GetParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue();
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명  : fn_SetBgColor_list
 * 설명      : 미확정 목록의 배경색 설정
 ***********************************************/
scwin.fn_SetBgColor_list = function() {
    //그리드 컬럼 ID 구하기
    var arrColID = [];
    for (var i = 0; i < grd_List.getTotalCol(); i++) {
        arrColID.push(grd_List.getColumnID(i));
    }

    //입금전에 코드 발급한 건의 배경색 Light Yellow로 설정
    for (var j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_List, arrColID[j], 'BgColor', "{decode(VALID_YN,'N','#FF9900',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.img_TRD_DD_onclick = function() {
    popUpCalendar2(edt_TRD_DD_START);
};
scwin.dts_List_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_List);
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    }
    scwin.fn_SetBgColor_list(); //그리드 배경색 설정
    $c.cm.CloseWin(rowcount, grd_List);
    txb_TotalCnt.setValue("총 " + rowcount + "건");
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_search();
};
scwin.grd_List_OnHeadCheckClick = function(col, colid, bCheck) {
    fn_CheckAll(bCheck);
};
scwin.grd_List_OnCheckClick = function(col, colid, bCheck) {
    fn_Check(col, bCheck, true);
};
scwin.img_TO_TRNSM_DD_onclick = function() {
    popUpCalendar2(edt_TRD_DD_END);
};
scwin.txb_pDEPOPRN_NM_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pDEPOPRN_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        }
    }
};
scwin.btn_search_realtime_onclick = function() {
    scwin.ins_search_realtime();
};
